#include "Variation.h"
juce::var Variation::toVar() const
{
    auto* o=new juce::DynamicObject(); o->setProperty("id",id);o->setProperty("originalSampleId",originalSampleId);o->setProperty("name",name);o->setProperty("createdAt",createdAt);o->setProperty("outputPath",outputPath);o->setProperty("number",number);o->setProperty("seed",(juce::int64)seed);o->setProperty("locked",locked);o->setProperty("favorite",favorite);o->setProperty("deleted",deleted);o->setProperty("durationSeconds",durationSeconds);o->setProperty("sampleRate",sampleRate);o->setProperty("channels",channels);o->setProperty("bitDepth",bitDepth);o->setProperty("rms",rms);o->setProperty("peak",peak);o->setProperty("spectralCentroid",spectralCentroid);o->setProperty("crestFactor",crestFactor);juce::Array<juce::var>a;for(auto&e:effects)a.add(e.toVar());o->setProperty("effects",juce::var(a));return juce::var(o);
}
bool Variation::fromVar(const juce::var& v,Variation& r)
{
    auto*o=v.getDynamicObject();if(!o)return false; r.id=o->getProperty("id").toString();r.originalSampleId=o->getProperty("originalSampleId").toString();r.name=o->getProperty("name").toString();r.createdAt=o->getProperty("createdAt").toString();r.outputPath=o->getProperty("outputPath").toString();r.number=(int)o->getProperty("number");r.seed=(juce::uint64)(juce::int64)o->getProperty("seed");r.locked=(bool)o->getProperty("locked");r.favorite=(bool)o->getProperty("favorite");r.deleted=(bool)o->getProperty("deleted");r.durationSeconds=(double)o->getProperty("durationSeconds");r.sampleRate=(double)o->getProperty("sampleRate");r.channels=(int)o->getProperty("channels");r.bitDepth=(int)o->getProperty("bitDepth");r.rms=(double)o->getProperty("rms");r.peak=(double)o->getProperty("peak");r.spectralCentroid=(double)o->getProperty("spectralCentroid");r.crestFactor=(double)o->getProperty("crestFactor");if(auto*a=o->getProperty("effects").getArray())for(const auto&x:*a){EffectSettings e;if(!EffectSettings::fromVar(x,e))return false;r.effects.push_back(e);}return r.id.isNotEmpty()&&r.originalSampleId.isNotEmpty()&&r.outputPath.isNotEmpty();
}
